-- =====================================================================
-- Flyway Unified Migration V1: Supermarket Management
-- Complete Normalized Schema + Master Reference Data + 100 Seed Rows
-- Charset: utf8mb4, Engine: InnoDB
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 0. Drop existing tables for fresh initialization
DROP TABLE IF EXISTS `sales_return_detail`;
DROP TABLE IF EXISTS `sales_return`;
DROP TABLE IF EXISTS `stock_take_detail`;
DROP TABLE IF EXISTS `stock_take`;
DROP TABLE IF EXISTS `stock_transfer_detail`;
DROP TABLE IF EXISTS `stock_transfer`;
DROP TABLE IF EXISTS `stock_out_detail`;
DROP TABLE IF EXISTS `stock_out`;
DROP TABLE IF EXISTS `stock_in_detail`;
DROP TABLE IF EXISTS `stock_in`;
DROP TABLE IF EXISTS `invoice_detail`;
DROP TABLE IF EXISTS `invoice`;
DROP TABLE IF EXISTS `warehouse_product`;
DROP TABLE IF EXISTS `product`;
DROP TABLE IF EXISTS `warehouse`;
DROP TABLE IF EXISTS `supplier`;
DROP TABLE IF EXISTS `customer`;
DROP TABLE IF EXISTS `employee`;
DROP TABLE IF EXISTS `shift_checklist_item`;
DROP TABLE IF EXISTS `shift_checklist`;
DROP TABLE IF EXISTS `checklist_item`;
DROP TABLE IF EXISTS `audit_log`;
DROP TABLE IF EXISTS `invalidated_token`;
DROP TABLE IF EXISTS `user_role`;
DROP TABLE IF EXISTS `user`;
DROP TABLE IF EXISTS `role`;
DROP TABLE IF EXISTS `address`;
DROP TABLE IF EXISTS `ward`;
DROP TABLE IF EXISTS `district`;
DROP TABLE IF EXISTS `city`;
DROP TABLE IF EXISTS `status_product`;
DROP TABLE IF EXISTS `status_invoice`;
DROP TABLE IF EXISTS `brand`;
DROP TABLE IF EXISTS `product_category`;
DROP TABLE IF EXISTS `unit`;
DROP TABLE IF EXISTS `position`;
DROP TABLE IF EXISTS `promotion`;
DROP TABLE IF EXISTS `code_sequence`;

SET FOREIGN_KEY_CHECKS = 1;

-- =====================================================================
-- 1. Identity & Authorization Tables
-- =====================================================================
CREATE TABLE `role` (
    `id` VARCHAR(36) NOT NULL,
    `name` VARCHAR(255) NULL,
    `code` VARCHAR(255) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_role_name` UNIQUE (`name`),
    CONSTRAINT `uk_role_code` UNIQUE (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `user` (
    `id` VARCHAR(36) NOT NULL,
    `username` VARCHAR(255) NOT NULL,
    `password` VARCHAR(255) NULL,
    `is_active` BOOLEAN NULL DEFAULT TRUE,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_user_username` UNIQUE (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `user_role` (
    `user_id` VARCHAR(36) NOT NULL,
    `role_id` VARCHAR(36) NOT NULL,
    PRIMARY KEY (`user_id`, `role_id`),
    CONSTRAINT `fk_user_role_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_user_role_role` FOREIGN KEY (`role_id`) REFERENCES `role` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `invalidated_token` (
    `id` VARCHAR(255) NOT NULL,
    `expiry_time` DATETIME(6) NULL,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- 2. Administrative Geography (City, District, Ward, Address)
-- =====================================================================
CREATE TABLE `city` (
    `id` VARCHAR(36) NOT NULL,
    `name` VARCHAR(255) NULL,
    `code` VARCHAR(255) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_city_code` UNIQUE (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `district` (
    `id` VARCHAR(36) NOT NULL,
    `name` VARCHAR(255) NULL,
    `code` VARCHAR(255) NULL,
    `city_id` VARCHAR(36) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_district_code` UNIQUE (`code`),
    CONSTRAINT `fk_district_city` FOREIGN KEY (`city_id`) REFERENCES `city` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ward` (
    `id` VARCHAR(36) NOT NULL,
    `name` VARCHAR(255) NULL,
    `code` VARCHAR(255) NULL,
    `district_id` VARCHAR(36) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_ward_code` UNIQUE (`code`),
    CONSTRAINT `fk_ward_district` FOREIGN KEY (`district_id`) REFERENCES `district` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `address` (
    `id` VARCHAR(36) NOT NULL,
    `street` VARCHAR(255) NULL,
    `ward_id` VARCHAR(36) NULL,
    `district_id` VARCHAR(36) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `fk_address_ward` FOREIGN KEY (`ward_id`) REFERENCES `ward` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_address_district` FOREIGN KEY (`district_id`) REFERENCES `district` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- 3. Master Catalogs & Lookup Tables
-- =====================================================================
CREATE TABLE `position` (
    `id` VARCHAR(36) NOT NULL,
    `name` VARCHAR(255) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    INDEX `idx_position_is_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `unit` (
    `id` VARCHAR(36) NOT NULL,
    `code` VARCHAR(255) NULL,
    `name` VARCHAR(255) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_unit_code` UNIQUE (`code`),
    INDEX `idx_unit_is_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `product_category` (
    `id` VARCHAR(36) NOT NULL,
    `code` VARCHAR(255) NULL,
    `name` VARCHAR(255) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_product_category_code` UNIQUE (`code`),
    INDEX `idx_product_category_is_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `brand` (
    `id` VARCHAR(36) NOT NULL,
    `code` VARCHAR(255) NULL,
    `name` VARCHAR(255) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_brand_code` UNIQUE (`code`),
    INDEX `idx_brand_is_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `status_invoice` (
    `id` VARCHAR(36) NOT NULL,
    `name` VARCHAR(255) NULL,
    `code` VARCHAR(255) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_status_invoice_name` UNIQUE (`name`),
    CONSTRAINT `uk_status_invoice_code` UNIQUE (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `status_product` (
    `id` VARCHAR(36) NOT NULL,
    `name` VARCHAR(255) NULL,
    `code` VARCHAR(255) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_status_product_name` UNIQUE (`name`),
    CONSTRAINT `uk_status_product_code` UNIQUE (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `promotion` (
    `id` VARCHAR(36) NOT NULL,
    `name` VARCHAR(255) NOT NULL,
    `voucher_code` VARCHAR(255) NULL,
    `limit_voucher` INT NULL,
    `description` TEXT NULL,
    `start_date` DATETIME(6) NULL,
    `end_date` DATETIME(6) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `ck_promotion_period` CHECK (`start_date` IS NULL OR `end_date` IS NULL OR `start_date` <= `end_date`),
    CONSTRAINT `ck_promotion_limit` CHECK (`limit_voucher` IS NULL OR `limit_voucher` >= 0),
    INDEX `idx_promotion_is_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- 4. Business Entities (Employee, Customer, Supplier, Warehouse)
-- =====================================================================
CREATE TABLE `employee` (
    `id` VARCHAR(36) NOT NULL,
    `code` VARCHAR(20) COLLATE utf8mb4_unicode_ci NOT NULL,
    `name` VARCHAR(255) NOT NULL,
    `gender` VARCHAR(10) NULL,
    `dob` DATE NULL,
    `phone_number` VARCHAR(255) NULL,
    `email` VARCHAR(255) NULL,
    `user_id` VARCHAR(36) NULL,
    `position_id` VARCHAR(36) NULL,
    `address_id` VARCHAR(36) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_employee_code` UNIQUE (`code`),
    CONSTRAINT `ck_employee_gender` CHECK (`gender` IS NULL OR `gender` IN ('Nam', 'Nữ', 'Khác')),
    CONSTRAINT `fk_employee_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_employee_position` FOREIGN KEY (`position_id`) REFERENCES `position` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_employee_address` FOREIGN KEY (`address_id`) REFERENCES `address` (`id`) ON DELETE SET NULL,
    INDEX `idx_employee_is_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `customer` (
    `id` VARCHAR(36) NOT NULL,
    `name` VARCHAR(255) NULL,
    `gender` VARCHAR(10) NULL,
    `dob` DATE NULL,
    `phone_number` VARCHAR(255) NULL,
    `email` VARCHAR(255) NULL,
    `accumulated_points` INT NOT NULL DEFAULT 0,
    `user_id` VARCHAR(36) NULL,
    `address_id` VARCHAR(36) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `ck_customer_points` CHECK (`accumulated_points` >= 0),
    CONSTRAINT `ck_customer_gender` CHECK (`gender` IS NULL OR `gender` IN ('Nam', 'Nữ', 'Khác')),
    CONSTRAINT `fk_customer_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE SET NULL,
    CONSTRAINT `fk_customer_address` FOREIGN KEY (`address_id`) REFERENCES `address` (`id`) ON DELETE SET NULL,
    INDEX `idx_customer_is_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `supplier` (
    `id` VARCHAR(36) NOT NULL,
    `name` VARCHAR(255) NOT NULL,
    `email` VARCHAR(255) NULL,
    `phone_number` VARCHAR(255) NULL,
    `more_info` VARCHAR(255) NULL,
    `contact_date` DATETIME(6) NULL,
    `address_id` VARCHAR(36) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `fk_supplier_address` FOREIGN KEY (`address_id`) REFERENCES `address` (`id`) ON DELETE SET NULL,
    INDEX `idx_supplier_is_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `warehouse` (
    `id` VARCHAR(36) NOT NULL,
    `name` VARCHAR(255) NOT NULL,
    `email` VARCHAR(255) NULL,
    `phone_number` VARCHAR(255) NULL,
    `more_info` VARCHAR(255) NULL,
    `establish_date` DATETIME(6) NULL,
    `address_id` VARCHAR(36) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `fk_warehouse_address` FOREIGN KEY (`address_id`) REFERENCES `address` (`id`) ON DELETE SET NULL,
    INDEX `idx_warehouse_is_deleted` (`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- 5. Product & Warehouse Inventory
-- =====================================================================
CREATE TABLE `product` (
    `id` VARCHAR(36) NOT NULL,
    `code` VARCHAR(20) NOT NULL,
    `barcode` VARCHAR(50) NULL,
    `name` VARCHAR(255) NOT NULL,
    `image` VARCHAR(255) NULL,
    `sale_price` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `cost_price` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `min_stock` INT NOT NULL DEFAULT 0,
    `vat` DECIMAL(5, 2) NOT NULL DEFAULT 0,
    `warranty` INT NULL,
    `description` TEXT NULL,
    `details` TEXT NULL,
    `product_category_id` VARCHAR(36) NULL,
    `unit_id` VARCHAR(36) NULL,
    `supplier_id` VARCHAR(36) NULL,
    `brand_id` VARCHAR(36) NULL,
    `promotion_id` VARCHAR(36) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_product_code` UNIQUE (`code`),
    CONSTRAINT `uk_product_barcode` UNIQUE (`barcode`),
    CONSTRAINT `ck_product_prices` CHECK (`sale_price` >= 0 AND `cost_price` >= 0),
    CONSTRAINT `ck_product_vat` CHECK (`vat` BETWEEN 0 AND 100),
    CONSTRAINT `ck_product_min_stock` CHECK (`min_stock` >= 0),
    CONSTRAINT `ck_product_warranty` CHECK (`warranty` IS NULL OR `warranty` >= 0),
    CONSTRAINT `fk_product_category` FOREIGN KEY (`product_category_id`) REFERENCES `product_category` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_product_unit` FOREIGN KEY (`unit_id`) REFERENCES `unit` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_product_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `supplier` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_product_brand` FOREIGN KEY (`brand_id`) REFERENCES `brand` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_product_promotion` FOREIGN KEY (`promotion_id`) REFERENCES `promotion` (`id`) ON DELETE RESTRICT,
    INDEX `idx_product_is_deleted` (`is_deleted`),
    INDEX `idx_product_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `warehouse_product` (
    `id` VARCHAR(36) NOT NULL,
    `available_quantity` INT NOT NULL DEFAULT 0,
    `warehouse_id` VARCHAR(36) NOT NULL,
    `product_id` VARCHAR(36) NOT NULL,
    `status_product_id` VARCHAR(36) NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_warehouse_product` UNIQUE (`warehouse_id`, `product_id`),
    CONSTRAINT `ck_warehouse_product_quantity` CHECK (`available_quantity` >= 0),
    CONSTRAINT `fk_wp_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_wp_product` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_wp_status_product` FOREIGN KEY (`status_product_id`) REFERENCES `status_product` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- 6. Sales Invoices
-- =====================================================================
CREATE TABLE `invoice` (
    `id` VARCHAR(36) NOT NULL,
    `code` VARCHAR(20) NOT NULL,
    `invoice_create_date` DATETIME(6) NOT NULL,
    `discount` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `total_product` INT NOT NULL DEFAULT 0,
    `total_price` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `payment_method` VARCHAR(20) NOT NULL DEFAULT 'CASH',
    `amount_paid` DECIMAL(15, 2) NULL,
    `change_amount` DECIMAL(15, 2) NULL,
    `status_invoice_id` VARCHAR(36) NOT NULL,
    `customer_id` VARCHAR(36) NULL,
    `employee_id` VARCHAR(36) NOT NULL,
    `warehouse_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_invoice_code` UNIQUE (`code`),
    CONSTRAINT `ck_invoice_amounts` CHECK (`discount` >= 0 AND `total_price` >= 0 AND `total_product` >= 0),
    CONSTRAINT `ck_invoice_payment_method` CHECK (`payment_method` IN ('CASH', 'CARD', 'TRANSFER')),
    CONSTRAINT `ck_invoice_paid` CHECK (`amount_paid` IS NULL OR `amount_paid` >= 0),
    CONSTRAINT `fk_invoice_status` FOREIGN KEY (`status_invoice_id`) REFERENCES `status_invoice` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_invoice_customer` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_invoice_employee` FOREIGN KEY (`employee_id`) REFERENCES `employee` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_invoice_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`) ON DELETE RESTRICT,
    INDEX `idx_invoice_is_deleted` (`is_deleted`),
    INDEX `idx_invoice_create_date` (`invoice_create_date`),
    INDEX `idx_invoice_employee_date` (`employee_id`, `invoice_create_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `invoice_detail` (
    `id` VARCHAR(36) NOT NULL,
    `quantity` INT NOT NULL,
    `input_price` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `sale_price` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `discount_percent` DECIMAL(5, 2) NOT NULL DEFAULT 0,
    `line_total` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `invoice_id` VARCHAR(36) NOT NULL,
    `product_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_invoice_detail_product` UNIQUE (`invoice_id`, `product_id`),
    CONSTRAINT `ck_invoice_detail_quantity` CHECK (`quantity` > 0),
    CONSTRAINT `ck_invoice_detail_prices` CHECK (`input_price` >= 0 AND `sale_price` >= 0 AND `line_total` >= 0),
    CONSTRAINT `ck_invoice_detail_discount` CHECK (`discount_percent` BETWEEN 0 AND 100),
    CONSTRAINT `fk_id_invoice` FOREIGN KEY (`invoice_id`) REFERENCES `invoice` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_id_product` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- 7. Warehouse Stock Receipts & Issues
-- =====================================================================
CREATE TABLE `stock_in` (
    `id` VARCHAR(36) NOT NULL,
    `code` VARCHAR(20) NOT NULL,
    `stock_in_date` DATETIME(6) NOT NULL,
    `total_product` INT NOT NULL DEFAULT 0,
    `total_price` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `status_invoice_id` VARCHAR(36) NOT NULL,
    `supplier_id` VARCHAR(36) NOT NULL,
    `warehouse_id` VARCHAR(36) NOT NULL,
    `employee_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_stock_in_code` UNIQUE (`code`),
    CONSTRAINT `ck_stock_in_amounts` CHECK (`total_price` >= 0 AND `total_product` >= 0),
    CONSTRAINT `fk_si_status` FOREIGN KEY (`status_invoice_id`) REFERENCES `status_invoice` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_si_supplier` FOREIGN KEY (`supplier_id`) REFERENCES `supplier` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_si_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_si_employee` FOREIGN KEY (`employee_id`) REFERENCES `employee` (`id`) ON DELETE RESTRICT,
    INDEX `idx_stock_in_is_deleted` (`is_deleted`),
    INDEX `idx_stock_in_date` (`stock_in_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `stock_in_detail` (
    `id` VARCHAR(36) NOT NULL,
    `quantity` INT NOT NULL,
    `input_price` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `sale_price` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `lot_number` VARCHAR(50) NULL,
    `expiry_date` DATE NULL,
    `stock_in_id` VARCHAR(36) NOT NULL,
    `product_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_stock_in_detail_product` UNIQUE (`stock_in_id`, `product_id`),
    CONSTRAINT `ck_stock_in_detail_quantity` CHECK (`quantity` > 0),
    CONSTRAINT `ck_stock_in_detail_prices` CHECK (`input_price` >= 0 AND `sale_price` >= 0),
    CONSTRAINT `fk_sid_stock_in` FOREIGN KEY (`stock_in_id`) REFERENCES `stock_in` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_sid_product` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`) ON DELETE RESTRICT,
    INDEX `idx_sid_expiry_date` (`expiry_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `stock_out` (
    `id` VARCHAR(36) NOT NULL,
    `code` VARCHAR(20) NOT NULL,
    `stock_out_date` DATETIME(6) NOT NULL,
    `total_product` INT NOT NULL DEFAULT 0,
    `total_price` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `reason` VARCHAR(255) NULL,
    `status_invoice_id` VARCHAR(36) NOT NULL,
    `customer_id` VARCHAR(36) NULL,
    `employee_id` VARCHAR(36) NOT NULL,
    `warehouse_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_stock_out_code` UNIQUE (`code`),
    CONSTRAINT `ck_stock_out_amounts` CHECK (`total_price` >= 0 AND `total_product` >= 0),
    CONSTRAINT `fk_so_status` FOREIGN KEY (`status_invoice_id`) REFERENCES `status_invoice` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_so_customer` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_so_employee` FOREIGN KEY (`employee_id`) REFERENCES `employee` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_so_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`) ON DELETE RESTRICT,
    INDEX `idx_stock_out_is_deleted` (`is_deleted`),
    INDEX `idx_stock_out_date` (`stock_out_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `stock_out_detail` (
    `id` VARCHAR(36) NOT NULL,
    `quantity` INT NOT NULL,
    `input_price` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `sale_price` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `total_price` DECIMAL(15, 2) NOT NULL DEFAULT 0,
    `stock_out_id` VARCHAR(36) NOT NULL,
    `product_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_stock_out_detail_product` UNIQUE (`stock_out_id`, `product_id`),
    CONSTRAINT `ck_stock_out_detail_quantity` CHECK (`quantity` > 0),
    CONSTRAINT `ck_stock_out_detail_prices` CHECK (`input_price` >= 0 AND `sale_price` >= 0 AND `total_price` >= 0),
    CONSTRAINT `fk_sod_stock_out` FOREIGN KEY (`stock_out_id`) REFERENCES `stock_out` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_sod_product` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- 8. Store Operations (Transfer, Take, Return)
-- =====================================================================
CREATE TABLE `stock_transfer` (
    `id` VARCHAR(36) NOT NULL,
    `code` VARCHAR(20) NOT NULL,
    `transfer_date` DATETIME(6) NOT NULL,
    `note` VARCHAR(255) NULL,
    `total_product` INT NOT NULL DEFAULT 0,
    `from_warehouse_id` VARCHAR(36) NOT NULL,
    `to_warehouse_id` VARCHAR(36) NOT NULL,
    `employee_id` VARCHAR(36) NOT NULL,
    `status_invoice_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_stock_transfer_code` UNIQUE (`code`),
    CONSTRAINT `chk_stock_transfer_total_product` CHECK (`total_product` > 0),
    CONSTRAINT `chk_stock_transfer_warehouses` CHECK (`from_warehouse_id` <> `to_warehouse_id`),
    CONSTRAINT `fk_stf_from_warehouse` FOREIGN KEY (`from_warehouse_id`) REFERENCES `warehouse` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_stf_to_warehouse` FOREIGN KEY (`to_warehouse_id`) REFERENCES `warehouse` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_stf_employee` FOREIGN KEY (`employee_id`) REFERENCES `employee` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_stf_status` FOREIGN KEY (`status_invoice_id`) REFERENCES `status_invoice` (`id`) ON DELETE RESTRICT,
    INDEX `idx_stock_transfer_is_deleted` (`is_deleted`),
    INDEX `idx_stock_transfer_date` (`transfer_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `stock_transfer_detail` (
    `id` VARCHAR(36) NOT NULL,
    `quantity` INT NOT NULL,
    `stock_transfer_id` VARCHAR(36) NOT NULL,
    `product_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_stock_transfer_detail` UNIQUE (`stock_transfer_id`, `product_id`),
    CONSTRAINT `chk_stfd_quantity` CHECK (`quantity` > 0),
    CONSTRAINT `fk_stfd_stock_transfer` FOREIGN KEY (`stock_transfer_id`) REFERENCES `stock_transfer` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_stfd_product` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `stock_take` (
    `id` VARCHAR(36) NOT NULL,
    `code` VARCHAR(20) NOT NULL,
    `stock_take_date` DATETIME(6) NOT NULL,
    `note` VARCHAR(255) NULL,
    `total_difference` INT NOT NULL DEFAULT 0,
    `warehouse_id` VARCHAR(36) NOT NULL,
    `employee_id` VARCHAR(36) NOT NULL,
    `status_invoice_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_stock_take_code` UNIQUE (`code`),
    CONSTRAINT `fk_st_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_st_employee` FOREIGN KEY (`employee_id`) REFERENCES `employee` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_st_status` FOREIGN KEY (`status_invoice_id`) REFERENCES `status_invoice` (`id`) ON DELETE RESTRICT,
    INDEX `idx_stock_take_is_deleted` (`is_deleted`),
    INDEX `idx_stock_take_date` (`stock_take_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `stock_take_detail` (
    `id` VARCHAR(36) NOT NULL,
    `system_quantity` INT NOT NULL,
    `counted_quantity` INT NOT NULL,
    `difference` INT NOT NULL,
    `stock_take_id` VARCHAR(36) NOT NULL,
    `product_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_stock_take_detail` UNIQUE (`stock_take_id`, `product_id`),
    CONSTRAINT `chk_std_quantities` CHECK (`system_quantity` >= 0 AND `counted_quantity` >= 0),
    CONSTRAINT `chk_std_difference` CHECK (`difference` = `counted_quantity` - `system_quantity`),
    CONSTRAINT `fk_std_stock_take` FOREIGN KEY (`stock_take_id`) REFERENCES `stock_take` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_std_product` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sales_return` (
    `id` VARCHAR(36) NOT NULL,
    `code` VARCHAR(20) NOT NULL,
    `return_date` DATETIME(6) NOT NULL,
    `reason` VARCHAR(255) NOT NULL,
    `total_product` INT NOT NULL,
    `refund_amount` DECIMAL(15, 2) NOT NULL,
    `refund_method` VARCHAR(20) NOT NULL,
    `invoice_id` VARCHAR(36) NOT NULL,
    `customer_id` VARCHAR(36) NULL,
    `warehouse_id` VARCHAR(36) NOT NULL,
    `employee_id` VARCHAR(36) NOT NULL,
    `status_invoice_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    `is_deleted` BOOLEAN NOT NULL DEFAULT FALSE,
    `deleted_date` DATETIME(6) NULL,
    `deleted_by` VARCHAR(255) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_sales_return_code` UNIQUE (`code`),
    CONSTRAINT `chk_sales_return_total_product` CHECK (`total_product` > 0),
    CONSTRAINT `chk_sales_return_refund` CHECK (`refund_amount` >= 0),
    CONSTRAINT `chk_sales_return_refund_method` CHECK (`refund_method` IN ('CASH', 'CARD', 'TRANSFER')),
    CONSTRAINT `fk_sr_invoice` FOREIGN KEY (`invoice_id`) REFERENCES `invoice` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_sr_customer` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_sr_warehouse` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_sr_employee` FOREIGN KEY (`employee_id`) REFERENCES `employee` (`id`) ON DELETE RESTRICT,
    CONSTRAINT `fk_sr_status` FOREIGN KEY (`status_invoice_id`) REFERENCES `status_invoice` (`id`) ON DELETE RESTRICT,
    INDEX `idx_sales_return_is_deleted` (`is_deleted`),
    INDEX `idx_sales_return_date` (`return_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sales_return_detail` (
    `id` VARCHAR(36) NOT NULL,
    `quantity` INT NOT NULL,
    `unit_refund` DECIMAL(15, 2) NOT NULL,
    `line_total` DECIMAL(15, 2) NOT NULL,
    `sales_return_id` VARCHAR(36) NOT NULL,
    `product_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_sales_return_detail` UNIQUE (`sales_return_id`, `product_id`),
    CONSTRAINT `chk_srd_quantity` CHECK (`quantity` > 0),
    CONSTRAINT `chk_srd_amounts` CHECK (`unit_refund` >= 0 AND `line_total` >= 0),
    CONSTRAINT `fk_srd_sales_return` FOREIGN KEY (`sales_return_id`) REFERENCES `sales_return` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_srd_product` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- 9. Shift Checklists
-- =====================================================================
CREATE TABLE `checklist_item` (
    `id` VARCHAR(36) NOT NULL,
    `code` VARCHAR(50) NOT NULL,
    `label` VARCHAR(255) NOT NULL,
    `group_code` VARCHAR(20) NOT NULL,
    `sort_order` INT NOT NULL,
    `is_active` BOOLEAN NOT NULL DEFAULT TRUE,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_checklist_item_code` UNIQUE (`code`),
    CONSTRAINT `ck_checklist_item_group` CHECK (`group_code` IN ('START', 'END'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `shift_checklist` (
    `id` VARCHAR(36) NOT NULL,
    `user_id` VARCHAR(36) NOT NULL,
    `work_date` DATE NOT NULL,
    `shift_code` VARCHAR(50) NOT NULL,
    `is_completed` BOOLEAN DEFAULT FALSE,
    `notes` TEXT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_user_shift_date` UNIQUE (`user_id`, `work_date`, `shift_code`),
    CONSTRAINT `fk_shift_checklist_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE,
    CONSTRAINT `ck_shift_checklist_shift` CHECK (`shift_code` IN ('MORNING', 'AFTERNOON', 'NIGHT'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `shift_checklist_item` (
    `id` VARCHAR(36) NOT NULL,
    `shift_checklist_id` VARCHAR(36) NOT NULL,
    `checklist_item_id` VARCHAR(36) NOT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `uk_shift_checklist_item` UNIQUE (`shift_checklist_id`, `checklist_item_id`),
    CONSTRAINT `fk_sci_shift_checklist` FOREIGN KEY (`shift_checklist_id`) REFERENCES `shift_checklist` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_sci_checklist_item` FOREIGN KEY (`checklist_item_id`) REFERENCES `checklist_item` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- 10. System Audit Log & Business Code Sequences
-- =====================================================================
CREATE TABLE `audit_log` (
    `id` VARCHAR(36) NOT NULL,
    `action` VARCHAR(20) NOT NULL,
    `resource` VARCHAR(50) NOT NULL,
    `http_method` VARCHAR(10) NOT NULL,
    `path` VARCHAR(255) NOT NULL,
    `reference` VARCHAR(255) NULL,
    `username` VARCHAR(255) NULL,
    `ip_address` VARCHAR(45) NULL,
    `success` BOOLEAN NOT NULL,
    `status_code` INT NOT NULL,
    `error_code` INT NULL,
    `created_by` VARCHAR(255) NOT NULL,
    `created_date` DATETIME(6) NOT NULL,
    `modified_by` VARCHAR(255) NULL,
    `modified_date` DATETIME(6) NULL,
    PRIMARY KEY (`id`),
    CONSTRAINT `chk_audit_log_action` CHECK (`action` IN ('CREATE', 'UPDATE', 'DELETE', 'LOGIN', 'LOGOUT')),
    INDEX `idx_audit_log_created_date` (`created_date`),
    INDEX `idx_audit_log_username` (`username`, `created_date`),
    INDEX `idx_audit_log_resource` (`resource`, `created_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `code_sequence` (
    `name` VARCHAR(50) NOT NULL,
    `prefix` VARCHAR(10) NOT NULL,
    `padding` INT NOT NULL,
    `next_value` BIGINT NOT NULL,
    PRIMARY KEY (`name`),
    CONSTRAINT `ck_code_sequence_next_value` CHECK (`next_value` > 0),
    CONSTRAINT `ck_code_sequence_padding` CHECK (`padding` BETWEEN 1 AND 18)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

